//! GB18030 as PHP has it, the 2000 edition:
//!
//! ```php
//! bin2hex(mb_chr(0xE78D, 'GB18030'));  // "a6d9"
//! ```
//!
//! `encoding_rs` implements the WHATWG standard's newer mapping. Where that differs from
//! PHP, `data/gb18030-patches.bin` holds PHP's bytes, generated by
//! `examples/generate_gb.rs`: records of nine bytes, the code point, the
//! number of bytes and up to four bytes.

use super::BAD;
use crate::encoding::read_u32;

const PATCHES: &[u8] = include_bytes!("../../data/gb18030-patches.bin");

fn patches() -> &'static [[u8; 9]] {
    PATCHES.as_chunks::<9>().0
}

fn patch_bytes(record: &[u8; 9]) -> &[u8] {
    &record[5..5 + usize::from(record[4])]
}

pub fn encode(point: u32, output: &mut Vec<u8>) -> bool {
    if let Some(record) = patches()
        .iter()
        .find(|record| read_u32(&record[..]) == point)
    {
        output.extend_from_slice(patch_bytes(record));
        return true;
    }
    let Some(character) = char::from_u32(point) else {
        return false;
    };
    let mut buffer = [0; 4];
    let (bytes, _, unmappable) = encoding_rs::GB18030.encode(character.encode_utf8(&mut buffer));
    if unmappable {
        return false;
    }
    output.extend_from_slice(&bytes);
    true
}

/// A lead byte from 0x81 to 0xFE starts two bytes, or four when a digit
/// follows it. Each such sequence is decoded on its own, so a malformed one
/// cannot swallow the next character.
pub fn decode(bytes: &[u8]) -> Vec<u32> {
    let mut points = Vec::new();
    let mut index = 0;
    while index < bytes.len() {
        match bytes[index] {
            byte @ 0x00..=0x7F => {
                points.push(u32::from(byte));
                index += 1;
            }
            0x80 | 0xFF => {
                points.push(BAD);
                index += 1;
            }
            _ => {
                let length = if bytes.get(index + 1).is_some_and(u8::is_ascii_digit) {
                    4
                } else {
                    2
                };
                let end = (index + length).min(bytes.len());
                let sequence = &bytes[index..end];
                match patches()
                    .iter()
                    .find(|record| patch_bytes(record) == sequence)
                {
                    Some(record) => points.push(read_u32(&record[..])),
                    None => decode_with_encoding_rs(sequence, &mut points),
                }
                index = end;
            }
        }
    }
    points
}

/// Appends what `encoding_rs` makes of the bytes, with `BAD` for each
/// malformed part.
fn decode_with_encoding_rs(bytes: &[u8], points: &mut Vec<u32>) {
    let mut decoder = encoding_rs::GB18030.new_decoder_without_bom_handling();
    let mut text = String::with_capacity(bytes.len() * 4 + 16);
    let mut offset = 0;
    loop {
        let (result, read) =
            decoder.decode_to_string_without_replacement(&bytes[offset..], &mut text, true);
        offset += read;
        points.extend(text.chars().map(u32::from));
        text.clear();
        match result {
            encoding_rs::DecoderResult::InputEmpty => break,
            encoding_rs::DecoderResult::Malformed(_, _) => points.push(BAD),
            encoding_rs::DecoderResult::OutputFull => text.reserve(bytes.len() * 4 + 16),
        }
    }
}
